package com.magdi.tube;
import android.app.*;import android.os.Bundle;import android.content.*;import android.widget.*;import org.json.*;
/** Phone-only support entry. Advanced local sessions remain available during rollout. */
public final class SupportActivity extends Activity {
 boolean ar,busy;LinearLayout body;TextView status,id;Switch automatic;String supportId="";
 String t(String en,String arabic){return ar?arabic:en;}
 public void onCreate(Bundle b){super.onCreate(b);ar=getIntent().hasExtra("language")?"ar".equals(getIntent().getStringExtra("language")):getResources().getConfiguration().getLocales().get(0).getLanguage().equals("ar");ScrollView scroll=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setLayoutDirection(ar?android.view.View.LAYOUT_DIRECTION_RTL:android.view.View.LAYOUT_DIRECTION_LTR);int pad=(int)(20*getResources().getDisplayMetrics().density);body.setPadding(pad,pad,pad,pad);scroll.addView(body);setContentView(scroll);
  text(t("Support & diagnostics","الدعم والتشخيص"),25);text(t("Report a problem in one step. Give the developer your support ID and the approximate time of the problem.","بلّغ عن المشكلة بخطوة واحدة. ابعت للمطور رقم الدعم ووقت المشكلة التقريبي."),17);
  id=text("…",20);id.setTextIsSelectable(true);button(t("Copy support ID","نسخ رقم الدعم"),()->{if(supportId.isEmpty())return;((ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("MM support ID",supportId));Toast.makeText(this,t("Copied","تم النسخ"),android.widget.Toast.LENGTH_SHORT).show();});
  status=text("",16);automatic=new Switch(this);automatic.setText(t("Automatically send diagnostics (optional)","إرسال التشخيص تلقائيًا (اختياري)"));body.addView(automatic);automatic.setOnClickListener(v->{boolean on=automatic.isChecked();automatic.setChecked(!on);if(on)consent(()->SupportReporter.changeConsent(true,s->refresh()));else SupportReporter.changeConsent(false,s->refresh());});
  button(t("Send report now","إرسال تقرير الآن"),()->{if(busy)return;consent(()->{busy=true;status.setText(t("Sending…","جارٍ الإرسال…"));SupportReporter.send(s->{busy=false;refresh();Toast.makeText(this,message(s),android.widget.Toast.LENGTH_LONG).show();});});});
  String privacy=t("Only technical events, timing/counters, device model and app/system versions are sent to the developer's Supabase database in Frankfurt. No watched titles, searches, URLs, account details, passwords, cookies, location or phone identifiers. Supabase receives your IP to handle the connection; we do not store it in diagnostic reports. This is a random ID for this app installation, different in Tube and IPTV; reinstalling or deleting reports resets it.","يُرسل فقط أحداث تقنية وأوقات وأرقام أداء وموديل الجهاز وإصدارات التطبيق والنظام إلى قاعدة بيانات المطور على Supabase في فرانكفورت. لا تُرسل عناوين المشاهدة أو البحث أو الروابط أو بيانات الحساب أو كلمات السر أو الكوكيز أو الموقع أو معرفات الهاتف. Supabase يستقبل عنوان IP لتوصيل الطلب؛ لا نخزنه في التقارير. الرقم عشوائي لهذا التثبيت ويختلف بين Tube وIPTV، ويتغير عند إعادة التثبيت أو حذف التقارير.");
  privacy+="\n\n"+t("Automatic sending is off by default. When enabled, small batches are attempted about every 2 hours, subject to Android battery/network limits. Reports are kept for up to 30 days, possibly less when storage limits are reached. Disabling stops future uploads; use Delete to remove reports already sent. Local safe history: last 24 hours / 256 events. Sending now includes the latest 128 events; it does not enable automatic sending.","الإرسال التلقائي مغلق افتراضيًا. عند تفعيله تُرسل دفعات صغيرة كل ساعتين تقريبًا حسب قيود البطارية والشبكة. تُحفظ التقارير حتى ٣٠ يومًا وقد تُحذف أبكر عند بلوغ حدود التخزين. الإيقاف يمنع الإرسال القادم؛ استخدم الحذف لإزالة التقارير المرسلة. السجل الآمن المحلي: آخر ٢٤ ساعة / ٢٥٦ حدثًا. إرسال الآن يشمل آخر ١٢٨ حدثًا ولا يفعّل الإرسال التلقائي.");
  final String policy=privacy; text(t("Optional technical diagnostics only. No account or watched-content data.","تشخيص تقني اختياري فقط. بدون بيانات الحساب أو المحتوى المشاهَد."),15);button(t("Privacy & retention","الخصوصية ومدة الاحتفاظ"),()->new AlertDialog.Builder(this).setTitle(t("Privacy","الخصوصية")).setMessage(policy).setPositiveButton(t("Close","إغلاق"),null).show());
  button(t("Share a report manually","مشاركة تقرير يدويًا"),()->SupportReporter.share(this,false));button(t("Copy report","نسخ التقرير"),()->SupportReporter.share(this,true));
  button(t("Delete sent reports & reset ID","حذف التقارير المرسلة وتغيير رقم الدعم"),()->new AlertDialog.Builder(this).setMessage(t("Stops automatic sending, deletes reports for this installation and changes its ID after the server confirms deletion. An internet connection is required. Exports saved outside the app are unaffected.","يوقف الإرسال ويحذف تقارير هذا التثبيت ويغير الرقم بعد تأكيد الخادم. يلزم اتصال بالإنترنت. الملفات المصدرة خارج التطبيق لا تتأثر.")).setPositiveButton(t("Delete","حذف"),(d,w)->{busy=true;SupportReporter.erase(s->{busy=false;refresh();Toast.makeText(this,message(s),android.widget.Toast.LENGTH_LONG).show();});}).setNegativeButton(t("Cancel","إلغاء"),null).show());
  button(t("Advanced: local log sessions","متقدم: جلسات اللوج المحلية"),()->startActivity(new Intent(this,DiagnosticsActivity.class).putExtra("language",ar?"ar":"en")));button(t("Back","رجوع"),this::finish);refresh();
 }
 private void consent(Runnable action){new AlertDialog.Builder(this).setTitle(t("Share technical diagnostics?","مشاركة التشخيص التقني؟")).setMessage(t("Send the technical data described on this screen to the developer's Supabase service? You can stop automatic sending and delete sent reports at any time.","إرسال البيانات التقنية الموضحة في هذه الشاشة إلى خدمة Supabase الخاصة بالمطور؟ يمكنك إيقاف الإرسال التلقائي وحذف التقارير المرسلة في أي وقت.")).setPositiveButton(t("Agree","موافق"),(d,w)->action.run()).setNegativeButton(t("Cancel","إلغاء"),null).show();}
 private void refresh(){SupportReporter.info(j->{if(isFinishing()||isDestroyed())return;supportId=j.optString("support_id");id.setText(t("Support ID: ","رقم الدعم: ")+supportId);automatic.setChecked(j.optBoolean("enabled"));long sent=j.optLong("last_sent");status.setText(message(j.optString("status"))+(sent>0?"\n"+t("Last delivered: ","آخر وصول ناجح: ")+java.text.DateFormat.getDateTimeInstance().format(new java.util.Date(sent)):""));});}
 private String message(String s){switch(s){case "sent":return t("Report delivered. Share your support ID with the developer.","وصل التقرير. ابعت رقم الدعم للمطور.");case "deleted":return t("Reports deleted; new support ID created.","اتحذفت التقارير واتعمل رقم دعم جديد.");case "limit":return t("Service limit reached. Try later or share manually.","وصلنا لحد الخدمة. جرّب لاحقًا أو شارك يدويًا.");case "failed":return t("Not delivered. Check internet; try again or share manually.","التقرير لم يصل. افحص الإنترنت وجرّب تاني أو شارك يدويًا.");default:return t("No report sent yet.","لم يتم إرسال تقرير بعد.");}}
 private TextView text(String s,int size){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setPadding(0,12,0,12);body.addView(v);return v;}
 private void button(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setAllCaps(false);body.addView(b,new LinearLayout.LayoutParams(-1,-2));b.setOnClickListener(v->{if(!busy)r.run();});}
}
